/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: key, entry
 *   Constants: none
 * Tests
 *   - review-only paths are the expected tracklist and member Artist entries; entry lists are the Album's and each member's
 *   - an entry agrees by name case-insensitively, by a name or alias found for its ID, or by the same ID under another name, whatever ID the saved entry keeps; never across roles
 *   - join phrases compare as bylines: a missing or invalid one is `, `, and the last entry's is ignored
 *   - saved and lookup lists are the same, extended by appended entries, or different
 *   - member states read the capture: unreadable or incomplete Credits are not complete, and an Artist Credit of any role counts
 *   - a lookup date adds precision only to the same year (and month) gaining a month or day
 *   - an entry counts as one identity by its MusicBrainz ID, else by its case-folded name
 * @end-catalog */

/**
 * The pure rules of applying metadata lookup values to an existing-Album review (lookupReviewValues.ts): when a lookup Artist entry
 * agrees with a saved one, how a saved entry list compares with a candidate's, what a review's capture lets change, whether a lookup
 * date only adds precision, and the identity an entry counts as. All names and identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import type { ImportArtistEntry } from '../../src/administration/import/adminImportDraft';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import {
    REVIEW_LOOKUP_LIMITS, addsDatePrecision, bylineJoinPhrase, compareReviewEntries, isEntryListPath, reviewAlbumState, reviewEntryAgrees, reviewIdentityKey, reviewMemberStates,
    reviewOnlyLookupPath
} from '../../src/administration/lookup/lookupReviewValues';
import { reviewLookupDocument, syntheticMbid } from '../support/catalogReviewLookupFixtures';

const key = (index: number) => `0000000c-0000-4000-8000-${String(index).padStart(12, '0')}`;
const entry = (name: string, extra: Partial<ImportArtistEntry> = {}, index = 0): ImportArtistEntry =>
    ({ key: key(index), name, role: 'primary', joinPhrase: null, musicBrainzId: null, ...extra });
const none = new Map<string, readonly string[]>();

test('review-only paths are the expected tracklist and member Artist entries; entry lists are the Album\'s and each member\'s', () => {
    assert.deepEqual(['album.expectedTracklist', 'tracks.slot.artists', 'album.artists', 'tracks.slot.title', 'album.label'].map(reviewOnlyLookupPath), [true, true, false, false, false]);
    assert.deepEqual(['album.artists', 'tracks.slot.artists', 'album.expectedTracklist', 'album.label', 'tracks.a.b.artists'].map(isEntryListPath), [true, true, false, false, false]);
    assert.deepEqual(REVIEW_LOOKUP_LIMITS, { identities: 512, answers: 406 });
});

test('an entry agrees by name case-insensitively, by a name or alias found for its ID, or by the same ID under another name, whatever ID the saved entry keeps; never across roles', () => {
    const found = new Map([[syntheticMbid(1), ['Synthetic Lead', 'シンセ リード']]]);
    // By name, case and surrounding space aside, and with only one side carrying an ID.
    assert.equal(reviewEntryAgrees(entry('synthetic lead '), entry('Synthetic Lead', { musicBrainzId: syntheticMbid(1) }), none), true);
    // By a credited, canonical or alias name the run found for the lookup entry's ID.
    assert.equal(reviewEntryAgrees(entry('シンセ リード'), entry('Synthetic Lead', { musicBrainzId: syntheticMbid(1) }), found), true);
    assert.equal(reviewEntryAgrees(entry('シンセ リード'), entry('Synthetic Lead', { musicBrainzId: syntheticMbid(1) }), none), false);
    assert.equal(reviewEntryAgrees(entry('シンセ リード'), entry('Synthetic Lead'), found), false, 'an alias needs the lookup entry\'s ID');
    // By the same stored ID under a different credited name.
    assert.equal(reviewEntryAgrees(entry('Old Name', { musicBrainzId: syntheticMbid(1) }), entry('New Name', { musicBrainzId: syntheticMbid(1) }), none), true);
    // A saved entry whose Artist keeps another ID still agrees by its name or a found alias (the ID difference is answered apart),
    // but never by the other ID alone.
    assert.equal(reviewEntryAgrees(entry('Synthetic Lead', { musicBrainzId: syntheticMbid(2) }), entry('Synthetic Lead', { musicBrainzId: syntheticMbid(1) }), none), true);
    assert.equal(reviewEntryAgrees(entry('シンセ リード', { musicBrainzId: syntheticMbid(2) }), entry('Synthetic Lead', { musicBrainzId: syntheticMbid(1) }), found), true);
    assert.equal(reviewEntryAgrees(entry('Old Name', { musicBrainzId: syntheticMbid(2) }), entry('New Name', { musicBrainzId: syntheticMbid(1) }), found), false);
    // The role must match.
    assert.equal(reviewEntryAgrees(entry('Synthetic Lead', { role: 'featured' }), entry('Synthetic Lead'), none), false);
    assert.equal(reviewEntryAgrees(null as unknown as ImportArtistEntry, entry('Synthetic Lead'), none), false);
});

test('join phrases compare as bylines: a missing or invalid one is `, `, and the last entry\'s is ignored', () => {
    assert.deepEqual([bylineJoinPhrase(null), bylineJoinPhrase(undefined), bylineJoinPhrase('\u0000'), bylineJoinPhrase(' '), bylineJoinPhrase(' & '), bylineJoinPhrase(', ')],
        [', ', ', ', ', ', ', ', ' & ', ', ']);
    const saved = [entry('A', {}, 1), entry('B', { joinPhrase: ' x ' }, 2)];
    // "A, B" saved without phrases agrees with a `, ` credit; the last phrase differs and is ignored.
    assert.deepEqual(compareReviewEntries(saved, [entry('A', { joinPhrase: ', ' }, 5), entry('B', {}, 6)], { found: none, append: false }), { kind: 'same' });
    // An invalid stored phrase reads as `, ` too.
    assert.deepEqual(compareReviewEntries([entry('A', { joinPhrase: '\u0007' }, 1), entry('B', {}, 2)], [entry('A', { joinPhrase: ', ' }), entry('B')], { found: none, append: false }), { kind: 'same' });
    // A changed phrase between entries is a difference.
    assert.deepEqual(compareReviewEntries(saved, [entry('A', { joinPhrase: ' & ' }), entry('B')], { found: none, append: true }), { kind: 'differs' });
});

test('saved and lookup lists are the same, extended by appended entries, or different', () => {
    const saved = [entry('A', { joinPhrase: ' & ' }, 1), entry('B', {}, 2)];
    const lookup = [entry('a', { joinPhrase: ' & ', musicBrainzId: syntheticMbid(1) }, 1), entry('B', { joinPhrase: ' feat. ', musicBrainzId: syntheticMbid(2) }, 2),
        entry('C', { role: 'featured', musicBrainzId: syntheticMbid(3) }, 3)];
    // Appending keeps the saved keys, names and roles, gives each its lookup ID and the last one the connecting phrase.
    assert.deepEqual(compareReviewEntries(saved, lookup, { found: none, append: true }), { kind: 'append', value: [
        { key: key(1), name: 'A', role: 'primary', joinPhrase: ' & ', musicBrainzId: syntheticMbid(1) },
        { key: key(2), name: 'B', role: 'primary', joinPhrase: ' feat. ', musicBrainzId: syntheticMbid(2) },
        { key: key(3), name: 'C', role: 'featured', joinPhrase: null, musicBrainzId: syntheticMbid(3) }] });
    // A member list never appends, and an added featured entry is a difference there.
    assert.deepEqual(compareReviewEntries(saved, lookup, { found: none, append: false }), { kind: 'differs' });
    // A saved ID stays; a lookup ID another entry already carries is not taken twice.
    const carrying = [entry('A', { musicBrainzId: syntheticMbid(9) }, 1), entry('B', {}, 2)];
    const appended = compareReviewEntries(carrying, [entry('A', { joinPhrase: ', ' }), entry('B', { joinPhrase: ', ', musicBrainzId: syntheticMbid(9) }), entry('C')],
        { found: none, append: true });
    assert.ok(appended.kind === 'append');
    assert.deepEqual(appended.value.map(item => item.musicBrainzId), [syntheticMbid(9), null, null]);
    // Reordered entries, a shorter list, and a saved list holding two names that fold equal each differ.
    assert.deepEqual(compareReviewEntries(saved, [entry('B', { joinPhrase: ' & ' }), entry('A')], { found: none, append: true }), { kind: 'differs' });
    assert.deepEqual(compareReviewEntries(saved, [entry('A')], { found: none, append: true }), { kind: 'differs' });
    assert.deepEqual(compareReviewEntries([entry('Duo', {}, 1), entry('DUO', {}, 2)], [entry('Duo'), entry('Other')], { found: none, append: true }), { kind: 'differs' });
    // Equal lists are the same; malformed input differs.
    assert.deepEqual(compareReviewEntries(saved, saved, { found: none, append: false }), { kind: 'same' });
    assert.deepEqual(compareReviewEntries([], [], { found: none, append: false }), { kind: 'same' });
    assert.deepEqual(compareReviewEntries(null as unknown as ImportArtistEntry[], saved, { found: none, append: true }), { kind: 'differs' });
});

test('member states read the capture: unreadable or incomplete Credits are not complete, and an Artist Credit of any role counts', () => {
    const doc = reviewLookupDocument({ members: [{ artists: [{ name: 'Synthetic Singer' }] }, { otherCredits: ['composer'] }, { otherCredits: ['organization'] },
        { complete: false, artists: [{ name: 'Synthetic Singer' }] }, { complete: 'unreadable' }, {}] });
    assert.deepEqual([...reviewMemberStates(doc).values()], [{ complete: true, hasArtistCredit: true }, { complete: true, hasArtistCredit: true }, { complete: true, hasArtistCredit: false },
        { complete: false, hasArtistCredit: true }, { complete: false, hasArtistCredit: false }, { complete: true, hasArtistCredit: false }]);
    for (const capture of [undefined, null, { members: 'x' }, { members: [null, { slotId: 1 }] }]) {
        assert.deepEqual(reviewMemberStates({ catalogCapture: capture } as unknown as AdminImportDocument).size, 0, JSON.stringify(capture));
    }
    assert.deepEqual([reviewAlbumState(reviewLookupDocument()), reviewAlbumState(reviewLookupDocument({ label: 'none' })), reviewAlbumState(reviewLookupDocument({ label: 'other', albumComplete: false })),
        reviewAlbumState({ catalogCapture: null } as unknown as AdminImportDocument)],
    [{ artists: true, label: true }, { artists: true, label: true }, { artists: false, label: false }, { artists: false, label: false }]);
});

test('a lookup date adds precision only to the same year (and month) gaining a month or day', () => {
    const date = (year: number, month: number | null = null, day: number | null = null) => ({ year, month, day });
    assert.deepEqual([addsDatePrecision(date(2020), date(2020, 5)), addsDatePrecision(date(2020), date(2020, 5, 1)), addsDatePrecision(date(2020, 5), date(2020, 5, 1)),
        addsDatePrecision(date(2020, 5), date(2020, 6, 1)), addsDatePrecision(date(2020), date(2021, 5)), addsDatePrecision(date(2020, 5, 1), date(2020, 5, 1)),
        addsDatePrecision(date(2020, 5), date(2020)), addsDatePrecision(null, date(2020, 5)), addsDatePrecision(date(2020), null)],
    [true, true, true, false, false, false, false, false, false]);
});

test('an entry counts as one identity by its MusicBrainz ID, else by its case-folded name', () => {
    assert.equal(reviewIdentityKey({ name: 'Synthetic Lead', musicBrainzId: syntheticMbid(1) }), `id:${syntheticMbid(1)}`);
    assert.equal(reviewIdentityKey({ name: 'Synthetic LEAD', musicBrainzId: null }), reviewIdentityKey({ name: 'synthetic lead', musicBrainzId: null }));
});
